export const facts={life_support_stable:['Life support repaired','Repairs preserve 2 extra oxygen on later rounds.'],signal_decoded:['Signal decoded','The rescue frequency returns in the finale.'],rescue_contact:['Rescue fleet contacted','The fleet has a confirmed rescue route.'],engineer_onboard:['Engineer rescued','The engineer restores 3 energy on later rounds.'],navigation_mapped:['Navigation mapped','Scanned coordinates guide the final jump.'],station_route:['Station route charted','A known destination for evacuation.'],shields_reinforced:['Shields reinforced','Prevent up to 4 oxygen loss on later rounds.'],beacon_followed:['Beacon followed','A hidden passage is now known.'],safe_detour:['Safe detour taken','The worst debris was avoided.'],station_powered:['Station power restored','The station supports evacuation.'],manual_dock:['Manual docking completed','A direct escape corridor is available.'],drone_deployed:['Rescue drone deployed','The drone guides the rescue fleet.']};
const roundFacts=[['life_support_stable','signal_decoded','rescue_contact'],['engineer_onboard','navigation_mapped','station_route'],['shields_reinforced','beacon_followed','safe_detour'],['station_powered','manual_dock','drone_deployed']];
export function applyStoryEffects(s,w){const before={oxygen:s.oxygen,energy:s.energy,chaos:s.chaos},f=s.facts||{},d={oxygen:[10,-8,-4][w],energy:[-8,-5,-12][w],chaos:[-12,15,3][w]},notes=[];if(f.life_support_stable){d.oxygen+=2;notes.push('Earlier life-support repairs preserve 2 oxygen.')}if(f.engineer_onboard){d.energy+=3;notes.push('Your rescued engineer restores 3 energy.')}if(f.shields_reinforced&&d.oxygen<0){d.oxygen+=Math.min(4,-d.oxygen);notes.push('Your reinforced shields reduce oxygen loss.')}for(const k of Object.keys(d))s[k]=Math.min(100,Math.max(0,s[k]+d[k]));const effects=Object.fromEntries(Object.keys(d).map(k=>[k,s[k]-before[k]]));s.consequences=[...Object.entries(effects).map(([k,v])=>`${k} ${v>=0?'+':''}${v}`),...notes];return {effects,callbacks:notes}}
export function rememberStory(s,w){s.facts||={};if(s.round<4)s.facts[roundFacts[s.round][w]]=true;s.memory=Object.keys(s.facts).filter(k=>facts[k]).map(id=>({id,title:facts[id][0],description:facts[id][1]}))}
export function storyCallback(s){const f=s.facts||{},n=s.round+1;if(n===1)return f.life_support_stable?'Your repaired life support buys time to help the stranger.':f.signal_decoded?'The decoded signal belongs to the engineer; they recognize your rescue frequency.':'The rescue fleet heard your distress call and needs a safe rendezvous.';if(n===2)return f.engineer_onboard?'The rescued engineer recognizes the beacon and promises to restore energy as you travel.':f.navigation_mapped?'Coordinates from your scanned core reveal a gap in the debris.':'Your chosen station route crosses the debris field.';if(n===3)return f.shields_reinforced?'Your reinforced shields protect remaining oxygen.':f.beacon_followed?'The beacon reveals a hidden station approach.':'Your safe detour brings you to the far side of the station.';return f.station_powered?'Your shared power brings the docking lights online.':f.manual_dock?'Your manual docking creates a direct escape corridor.':'Your rescue drone broadcasts your location to the fleet.'}
export function finishStory(s,w){const f=s.facts||{};let id,text;if(s.oxygen===0||s.energy===0){id='emergency_rescue';text='The Aurora exhausts its reserves. The crew abandons the ship and signals for emergency rescue.'}else if(w===0){id='crew_reunion';text='Everyone boards the Aurora for a shared journey home.'+(f.engineer_onboard?' The engineer you rescued keeps the engines running.':' The crew stabilizes the engines together.')}else if(w===1){id=f.navigation_mapped?'charted_jump':f.beacon_followed?'beacon_jump':'risky_jump';text=id==='charted_jump'?'Your scanned coordinates guide a mapped jump home.':id==='beacon_jump'?'The beacon lights a hidden jump corridor home.':'Without mapped coordinates, a risky jump leaves the crew far from its intended destination.'}else{id=f.rescue_contact||f.signal_decoded||f.drone_deployed?'fleet_rendezvous':'uncertain_wait';text=id==='fleet_rendezvous'?'Your earlier rescue signal guides the fleet to the Aurora.':'No rescue link was established earlier. The crew waits and broadcasts a new call for help.'}s.ending={id,title:id.split('_').map(x=>x[0].toUpperCase()+x.slice(1)).join(' ')};return `${text} Final reserves: ${s.oxygen}% oxygen and ${s.energy}% energy.`}
